/* ================= InvoiceForge pure functions (top-level, testable) ================= */
function round2(n){
  return Math.round((Number(n)||0)*100)/100;
}
function escapeHTML(s){
  return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function formatMoney(n){
  var v=round2(n);
  var neg=v<0; if(neg) v=-v;
  var parts=v.toFixed(2).split('.');
  parts[0]=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');
  return (neg?'-':'')+parts.join('.');
}
function lineTotal(item){
  return round2((Number(item.qty)||0)*(Number(item.price)||0));
}
function calcTotals(items, taxRate, discount){
  var subtotal=0;
  (items||[]).forEach(function(it){ subtotal=round2(subtotal+lineTotal(it)); });
  var disc=round2(Math.min(Number(discount)||0, subtotal));
  var taxable=round2(subtotal-disc);
  var tax=round2(taxable*(Number(taxRate)||0)/100);
  var total=round2(taxable+tax);
  return { subtotal:subtotal, discount:disc, taxable:taxable, tax:tax, total:total };
}
function intToCn(integer){
  var digits='零壹贰叁肆伍陆柒捌玖';
  var units=['','拾','佰','仟'];
  var bigUnits=['','万','亿','万亿'];
  integer=Math.floor(Math.abs(Number(integer)||0));
  if(integer===0) return '零';
  var s=String(integer);
  var groups=[];
  while(s.length){ groups.unshift(s.slice(-4)); s=s.slice(0,-4); }
  var out='';
  for(var g=0; g<groups.length; g++){
    var grpVal=parseInt(groups[g],10);
    var bigIdx=groups.length-1-g;
    if(grpVal===0) continue;
    if(out && groups[g].length===4 && groups[g].charAt(0)==='0') out+='零';
    var grp=String(grpVal), gs='', pendingZero=false;
    for(var i=0;i<grp.length;i++){
      var d=+grp.charAt(i), pos=grp.length-1-i;
      if(d===0){ pendingZero=true; continue; }
      if(pendingZero){ gs+='零'; pendingZero=false; }
      gs+=digits.charAt(d)+units[pos];
    }
    out+=gs+bigUnits[bigIdx];
  }
  return out;
}
function cnUpper(n){
  var v=round2(Number(n)||0);
  if(v<0) return '负'+cnUpper(-v);
  var digits='零壹贰叁肆伍陆柒捌玖';
  var integer=Math.floor(v);
  var cents=Math.round((v-integer)*100);
  var jiao=Math.floor(cents/10), fen=cents%10;
  var out=intToCn(integer)+'元';
  if(jiao===0&&fen===0) return out+'整';
  if(jiao>0) out+=digits.charAt(jiao)+'角';
  else if(fen>0) out+='零';
  if(fen>0) out+=digits.charAt(fen)+'分';
  else out+='整';
  return out;
}
function genInvoiceNo(date, seq){
  var d=date instanceof Date?date:new Date();
  var y=d.getFullYear(), m=('0'+(d.getMonth()+1)).slice(-2), day=('0'+d.getDate()).slice(-2);
  var s=('000'+(seq==null?1:seq)).slice(-4);
  return 'INV-'+y+m+day+'-'+s;
}
function defaultInvoice(){
  var today=new Date().toISOString().slice(0,10);
  return {
    title:'报价单', no:genInvoiceNo(new Date(),1), date:today, due:'',
    seller:{ name:'', tax:'', addr:'', bank:'' },
    buyer:{ name:'', tax:'', addr:'' },
    items:[ { name:'示例服务项', qty:1, price:1000 } ],
    taxRate:0, discount:0, notes:''
  };
}
function toJSON(inv){
  return JSON.stringify({ app:'InvoiceForge', version:1, invoice:inv }, null, 2);
}
function fromJSON(text){
  var data=JSON.parse(text);
  var inv=data&&data.invoice?data.invoice:data;
  if(!inv||!Array.isArray(inv.items)) throw new Error('invalid invoice');
  var base=defaultInvoice();
  for(var k in base) if(inv[k]===undefined) inv[k]=base[k];
  inv.items=inv.items.map(function(it){
    return { name:String(it.name||''), qty:Number(it.qty)||0, price:Number(it.price)||0 };
  });
  return inv;
}
function renderInvoice(inv){
  var t=calcTotals(inv.items, inv.taxRate, inv.discount);
  var rows='';
  (inv.items||[]).forEach(function(it,i){
    rows+='<tr><td>'+(i+1)+'</td><td>'+escapeHTML(it.name)+'</td>'
      +'<td class="num">'+(Number(it.qty)||0)+'</td>'
      +'<td class="num">'+formatMoney(it.price)+'</td>'
      +'<td class="num">'+formatMoney(lineTotal(it))+'</td></tr>';
  });
  var h='<h1>'+escapeHTML(inv.title||'报价单')+'</h1>'
    +'<div class="inv-no">编号：'+escapeHTML(inv.no||'-')+' ｜ 日期：'+escapeHTML(inv.date||'-')
    +(inv.due?' ｜ 有效期至：'+escapeHTML(inv.due):'')+'</div>'
    +'<div class="parties"><div class="party"><h4>开票方</h4>'
    +'<div><b>'+escapeHTML(inv.seller.name||'—')+'</b></div>'
    +(inv.seller.tax?'<div>税号：'+escapeHTML(inv.seller.tax)+'</div>':'')
    +(inv.seller.addr?'<div>'+escapeHTML(inv.seller.addr)+'</div>':'')
    +(inv.seller.bank?'<div>'+escapeHTML(inv.seller.bank)+'</div>':'')
    +'</div><div class="party"><h4>收票方</h4>'
    +'<div><b>'+escapeHTML(inv.buyer.name||'—')+'</b></div>'
    +(inv.buyer.tax?'<div>税号：'+escapeHTML(inv.buyer.tax)+'</div>':'')
    +(inv.buyer.addr?'<div>'+escapeHTML(inv.buyer.addr)+'</div>':'')
    +'</div></div>'
    +'<table><thead><tr><th style="width:36px">#</th><th>项目名称</th><th style="width:70px" class="num">数量</th>'
    +'<th style="width:100px" class="num">单价 (¥)</th><th style="width:110px" class="num">金额 (¥)</th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table>'
    +'<div class="totals">'
    +'<div><span>小计</span><span>¥ '+formatMoney(t.subtotal)+'</span></div>'
    +(t.discount>0?'<div><span>优惠</span><span>- ¥ '+formatMoney(t.discount)+'</span></div>':'')
    +(Number(inv.taxRate)>0?'<div><span>税额 ('+inv.taxRate+'%)</span><span>¥ '+formatMoney(t.tax)+'</span></div>':'')
    +'<div class="grand"><span>合计</span><span>¥ '+formatMoney(t.total)+'</span></div></div>'
    +'<div class="cnupper">金额大写：<b>'+cnUpper(t.total)+'</b></div>'
    +(inv.notes?'<div class="notes">'+escapeHTML(inv.notes)+'</div>':'')
    +'<div class="foot"><span>开票人签字：____________</span><span>InvoiceForge · 本地生成</span></div>';
  return h;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { round2:round2, escapeHTML:escapeHTML, formatMoney:formatMoney, lineTotal:lineTotal,
    calcTotals:calcTotals, intToCn:intToCn, cnUpper:cnUpper, genInvoiceNo:genInvoiceNo,
    defaultInvoice:defaultInvoice, toJSON:toJSON, fromJSON:fromJSON, renderInvoice:renderInvoice };
}
if (typeof window !== 'undefined') {
  window.InvoiceForgePure = { round2:round2, escapeHTML:escapeHTML, formatMoney:formatMoney, lineTotal:lineTotal,
    calcTotals:calcTotals, intToCn:intToCn, cnUpper:cnUpper, genInvoiceNo:genInvoiceNo,
    defaultInvoice:defaultInvoice, toJSON:toJSON, fromJSON:fromJSON, renderInvoice:renderInvoice };
}
